export const ORGANIZER_SEGMENT_MAP: Map<string, OrganizerSegment> = new Map(
  ORGANIZER_SEGMENTS.map((seg) => [seg.segment_id, seg])
);

/**
 * Normalizes segment IDs like "R006" or "R6" to the canonical 4-digit format "R0006".
 */
export function normalizeSegmentId(id: string): string {
  if (!id) return id;
  const clean = id.trim().toUpperCase();
  const match = clean.match(/^R0*(\d+)$/);
  if (match) {
    const num = parseInt(match[1], 10);
    return `R${num.toString().padStart(4, "0")}`;
  }
  return clean;
}
